def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    frame = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    best = None
    best_score = None
    for n in range(3, min(h, w) + 1):
        for r0 in range(h - n + 1):
            for c0 in range(w - n + 1):
                square = [row[c0:c0+n] for row in grid[r0:r0+n]]
                border = [square[0][c] for c in range(n)]
                border += [square[n-1][c] for c in range(n)]
                border += [square[r][0] for r in range(1, n-1)]
                border += [square[r][n-1] for r in range(1, n-1)]
                if any(v not in (0, frame) for v in border):
                    continue
                border_count = sum(v == frame for v in border)
                if border_count == 0:
                    continue
                inside = [square[r][c] for r in range(1, n-1) for c in range(1, n-1)]
                if not any(v not in (0, frame) for v in inside):
                    continue
                score = (border_count, sum(v != 0 for v in inside) / max(1, len(inside)))
                if best_score is None or score > best_score:
                    best_score = score
                    best = square
    return best[::-1]
